	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nativeCallbackDistinguishesChangedInputWorkFromItsPhysicalResponse(boolean filter) {
		var factory = SimpleValueFactory.getInstance();
		StatementPattern statement = new StatementPattern(Var.of("subject"),
				Var.of("predicate", factory.createIRI("urn:work:predicate")), Var.of("value"));
		TupleExpr expression = filter
				? new Filter(statement, new Compare(Var.of("value"),
						new ValueConstant(factory.createLiteral(0)), Compare.CompareOp.GE))
				: new Projection(statement,
						new ProjectionElemList(new ProjectionElem("subject"), new ProjectionElem("value")), false);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), expression);
		var runtime = mock(LmdbEstimatorRuntime.class);
		var provider = new LmdbPackedCostModel(runtime);
		RuntimeFeedbackContract[] contracts = new RuntimeFeedbackContract[2];
		double[] inputs = { 20.0d, 101.0d };
		for (int ordinal = 0; ordinal < inputs.length; ordinal++) {
			var output = new PackedCostEstimate();
			output.setRows(10.0d, inputs[ordinal]);
			var context = call.operatorContext(10.0d, 0);
			provider.refineOperator(call.query(), call.operatorRelationId(), context, output);
			assertEquals(10.0d, output.outputRows());
			if (filter) {
				assertEquals(PackedCostEstimate.CostScope.LOCAL, output.costScope());
				assertEquals(0.0d, output.sequentialRows());
				assertEquals(10.0d, output.expressionEvaluations());
			} else {
				assertEquals(inputs[ordinal], output.workRows());
			}
			new LmdbMappedFrontierLearningSession(runtime, call.query(), true)
					.applyOperator(call.operatorRelationId(), new int[] { call.inputRelationId() }, context, output,
							false);
			contracts[ordinal] = output.runtimeFeedbackContract();
			assertNotNull(contracts[ordinal]);
			assertEquals(filter, contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_PHYSICAL),
					"only the FILTER callback declares physical dimensions; the scalar price has no SOURCE unit");
			assertFalse(contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			assertFalse(contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
		}
		if (filter) {
			assertEquals(contracts[0].rawPrediction(), contracts[1].rawPrediction(),
					"native FILTER replaces the changed fallback with the same actual operator dimensions");
		} else {
			assertTrue(Double.isNaN(contracts[0].rawPrediction().sourceRows()));
			assertTrue(Double.isNaN(contracts[1].rawPrediction().sourceRows()),
					"changed scalar input work cannot mint a physical SOURCE prediction");
		}
		var oldDescriptor = (LmdbRuntimeFeedbackDescriptor) contracts[0].descriptor();
		var newDescriptor = (LmdbRuntimeFeedbackDescriptor) contracts[1].descriptor();
		System.out.println("SCALAR_WORK_COMPATIBILITY " + Map.of(
				"filter", filter,
				"logicalEqual", oldDescriptor.logicalKey().equals(newDescriptor.logicalKey()),
				"physicalEqual", oldDescriptor.physicalKey().equals(newDescriptor.physicalKey()),
				"applicabilityEqual", oldDescriptor.applicability().equals(newDescriptor.applicability()),
				"oldRaw", contracts[0].rawPrediction(), "newRaw", contracts[1].rawPrediction(),
				"oldPhysical", oldDescriptor.physicalKey().externalForm(),
				"newPhysical", newDescriptor.physicalKey().externalForm()));
	}

	@Test
	void capturedUntypedSourceCalibrationCannotCorrectADeclaredPhysicalPredictor() throws Exception {
		Path directory = temporary.resolve("captured-untyped-source");
		Files.createDirectories(directory);
		Files.writeString(directory.resolve("metadata.bin"), "metadata");
		byte[] captured;
		try (var input = getClass().getResourceAsStream("/legacy-untyped-source.operators")) {
			assertNotNull(input);
			captured = input.readAllBytes();
		}
		assertEquals("b6f9eb9a7641cdb856077d5c897045affd48337d9e32327710f467359b42218d",
				HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(captured)),
				"this fixture is the actual pre-quantity-policy sidecar, not a regenerated current-policy seed");
		Files.write(directory.resolveSibling(directory.getFileName().toString() + ".operators"), captured);
		var snapshot = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
		var feedback = new LmdbOperatorFeedbackStats(directory, () -> snapshot);
		assertTrue(feedback.planningRevision() > 0L, "the captured sidecar must actually load");

		var factory = SimpleValueFactory.getInstance();
		var expression = new Projection(new StatementPattern(Var.of("subject"),
				Var.of("predicate", factory.createIRI("urn:work:predicate")), Var.of("value")),
				new ProjectionElemList(new ProjectionElem("subject"), new ProjectionElem("value")), false);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), expression);
		var runtime = mock(LmdbEstimatorRuntime.class);
		var provider = new LmdbPackedCostModel(runtime);
		var scalar = new PackedCostEstimate();
		scalar.setRows(10.0d, 20.0d);
		var scalarContext = call.operatorContext(10.0d, 0);
		provider.refineOperator(call.query(), call.operatorRelationId(), scalarContext, scalar);
		new LmdbMappedFrontierLearningSession(runtime, call.query(), true).applyOperator(
				call.operatorRelationId(), new int[] { call.inputRelationId() }, scalarContext, scalar, false);
		var oldBase = (LmdbRuntimeFeedbackDescriptor) scalar.runtimeFeedbackContract().descriptor();
		var retainedSeeks = feedback.physicalPosterior(oldBase.logicalKey(), oldBase.physicalKey(),
				oldBase.applicability(), FrontierCostDimension.INDEX_SEEKS);
		assertNotNull(retainedSeeks, "unaffected physical dimensions from the old sidecar remain addressable");
		assertEquals(32L, retainedSeeks.exactEvidenceCount());

		var current = new PackedCostEstimate();
		current.setRows(10.0d, 101.0d);
		current.setLocalPhysicalCost(101.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
				0.0d, 0.0d, 0.0d);
		current.setObjectiveInterval(101.0d, 101.0d, 101.0d);
		var context = call.operatorContext(10.0d, 0);
		provider.refineOperator(call.query(), call.operatorRelationId(), context, current);
		assertEquals(101.0d, current.sequentialRows(), "the provider declared this physical SOURCE quantity");
		when(runtime.feedback()).thenReturn(feedback);
		new LmdbMappedFrontierLearningSession(runtime, call.query(), true).applyOperator(
				call.operatorRelationId(), new int[] { call.inputRelationId() }, context, current, false);
		var contract = current.runtimeFeedbackContract();
		assertNotNull(contract);
		var now = (LmdbRuntimeFeedbackDescriptor) contract.descriptor();
		assertEquals(oldBase.logicalKey(), now.logicalKey());
		assertEquals(oldBase.applicability(), now.applicability());
		assertEquals(oldBase.physicalKey(), now.physicalKey());
		assertTrue(contract.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
		assertFalse(contract.admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
		assertFalse(contract.admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
		assertEquals(10.0d, current.outputRows());
		assertEquals(101.0d, current.sequentialRows(),
				"legacy scalar-derived SOURCE calibration cannot correct a newly declared physical quantity");
		assertEquals(retainedSeeks, feedback.physicalPosterior(now.logicalKey(), now.physicalKey(),
				now.applicability(), FrontierCostDimension.INDEX_SEEKS));
	}

	@Test
	void declaredSourceForecastVariationRetainsCalibrationAcrossReopen() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		var expression = new Projection(new StatementPattern(Var.of("subject"),
				Var.of("predicate", factory.createIRI("urn:work:predicate")), Var.of("value")),
				new ProjectionElemList(new ProjectionElem("subject"), new ProjectionElem("value")), false);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), expression);
		var runtime = mock(LmdbEstimatorRuntime.class);
		var provider = new LmdbPackedCostModel(runtime);
		RuntimeFeedbackContract[] contracts = new RuntimeFeedbackContract[2];
		double[] forecasts = { 20.0d, 101.0d };
		for (int ordinal = 0; ordinal < forecasts.length; ordinal++) {
			var output = new PackedCostEstimate();
			output.setRows(10.0d, forecasts[ordinal]);
			output.setLocalPhysicalCost(forecasts[ordinal], 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
					0.0d, 0.0d, 0.0d);
			var context = call.operatorContext(10.0d, 0);
			provider.refineOperator(call.query(), call.operatorRelationId(), context, output);
			new LmdbMappedFrontierLearningSession(runtime, call.query(), true).applyOperator(
					call.operatorRelationId(), new int[] { call.inputRelationId() }, context, output, false);
			contracts[ordinal] = output.runtimeFeedbackContract();
			assertNotNull(contracts[ordinal]);
			assertTrue(contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
			assertEquals(forecasts[ordinal], contracts[ordinal].rawPrediction().sourceRows());
		}
		var first = (LmdbRuntimeFeedbackDescriptor) contracts[0].descriptor();
		var second = (LmdbRuntimeFeedbackDescriptor) contracts[1].descriptor();
		assertEquals(first.logicalKey(), second.logicalKey());
		assertEquals(first.applicability(), second.applicability());
		assertEquals(first.physicalKey(), second.physicalKey(), "typed numeric variation keeps its predictor identity");
		Path directory = temporary.resolve("typed-forecast-variation");
		Files.createDirectories(directory);
		Files.writeString(directory.resolve("metadata.bin"), "metadata");
		var snapshot = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
		var feedback = new LmdbOperatorFeedbackStats(directory, () -> snapshot);
		for (int observation = 0; observation < 32; observation++) {
			var contract = contracts[observation % contracts.length];
			long actualSource = (long) (contract.rawPrediction().sourceRows() * 2.0d);
			RuntimeFeedbackTarget target = feedback.resolveRuntimeFeedbackTarget(contract);
			target.open();
			target.close(10L, actualSource + 10.0d, actualSource, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		}
		feedback.persistIfDirty();
		var reopened = new LmdbOperatorFeedbackStats(directory, () -> snapshot);
		for (double forecast : forecasts) {
			var decision = reopened.physicalDimensionDecision(first.logicalKey(), first.physicalKey(),
					first.applicability(), FrontierCostDimension.SOURCE_ROWS_SCANNED, first.featureEnvelope(),
					forecast);
			assertTrue(decision.gate().appliesLearning());
			assertNotNull(decision.estimate());
			assertTrue(decision.estimate().correctedValue() > forecast,
					"legitimate typed forecast variation remains calibrated after reopen");
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void onlyDeclaredPhysicalQuantitiesAuthorizeSourceCalibration(boolean typedPhysical) {
		var factory = SimpleValueFactory.getInstance();
		var expression = new Projection(new StatementPattern(Var.of("subject"),
				Var.of("predicate", factory.createIRI("urn:work:predicate")), Var.of("value")),
				new ProjectionElemList(new ProjectionElem("subject"), new ProjectionElem("value")), false);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), expression);
		var runtime = mock(LmdbEstimatorRuntime.class);
		var provider = new LmdbPackedCostModel(runtime);
		RuntimeFeedbackContract[] contracts = new RuntimeFeedbackContract[2];
		double[] forecasts = { 20.0d, 101.0d };
		for (int ordinal = 0; ordinal < forecasts.length; ordinal++) {
			var output = new PackedCostEstimate();
			output.setRows(10.0d, forecasts[ordinal]);
			output.setObjectiveInterval(forecasts[ordinal], forecasts[ordinal], forecasts[ordinal]);
			if (typedPhysical) {
				// The same numeric forecast is a physical count only when the provider actually declares its unit.
				output.setLocalPhysicalCost(forecasts[ordinal], 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
						0.0d, 0.0d, 0.0d);
			}
			var context = call.operatorContext(10.0d, 0);
			provider.refineOperator(call.query(), call.operatorRelationId(), context, output);
			assertEquals(10.0d, output.outputRows());
			assertEquals(forecasts[ordinal], output.workRows());
			assertEquals(forecasts[ordinal], output.objectivePoint());
			new LmdbMappedFrontierLearningSession(runtime, call.query(), true).applyOperator(
					call.operatorRelationId(), new int[] { call.inputRelationId() }, context, output, false);
			contracts[ordinal] = output.runtimeFeedbackContract();
			assertNotNull(contracts[ordinal]);
			assertFalse(contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			assertFalse(contracts[ordinal].admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
		}
		var first = (LmdbRuntimeFeedbackDescriptor) contracts[0].descriptor();
		var second = (LmdbRuntimeFeedbackDescriptor) contracts[1].descriptor();
		assertEquals(first.logicalKey(), second.logicalKey());
		assertEquals(first.applicability(), second.applicability());
		assertEquals(first.physicalKey(), second.physicalKey(),
				"forecast variation within one quantity/model is not an identity change");
		for (var contract : contracts) {
			assertEquals(typedPhysical, contract.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL),
					"a scalar objective proxy does not declare measured source-row units");
		}
	}

	@Test
	void actualMemoizedPredictionCanPersistIndependentResourceCells() throws Exception {
		var runtime = mock(LmdbEstimatorRuntime.class);
		RuntimeFeedbackContract contract = actualMemoizedPrediction(runtime, 110_000.0d);
		assertTrue(contract.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
		assertTrue(Double.isFinite(contract.rawPrediction().sourceRows()));
		var descriptor = (LmdbRuntimeFeedbackDescriptor) contract.descriptor();
		Path directory = temporary.resolve("captured-memoized-resource-model");
		Files.createDirectories(directory);
		Files.writeString(directory.resolve("metadata.bin"), "metadata");
		var snapshot = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
		var feedback = new LmdbOperatorFeedbackStats(directory, () -> snapshot);
		for (int observation = 0; observation < 32; observation++) {
			RuntimeFeedbackTarget target = feedback.resolveRuntimeFeedbackTarget(contract);
			target.open();
			target.close(1_000L, 5_000.0d, 200L, 3L, 4L, 1_004L, 5L, 6L, 7L, 8L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		}
		feedback.persistIfDirty();
		var reopened = new LmdbOperatorFeedbackStats(directory, () -> snapshot);
		for (FrontierCostDimension dimension : new FrontierCostDimension[] { FrontierCostDimension.INDEX_SEEKS,
				FrontierCostDimension.ITERATOR_OPENS, FrontierCostDimension.EXPRESSION_EVALUATIONS,
				FrontierCostDimension.HASH_BUILD_ROWS, FrontierCostDimension.HASH_PROBE_ROWS,
				FrontierCostDimension.PATH_EXPANSIONS, FrontierCostDimension.RESULT_ROWS,
				FrontierCostDimension.REMOTE_CALLS }) {
			assertNotNull(reopened.physicalPosterior(descriptor.logicalKey(), descriptor.physicalKey(),
					descriptor.applicability(), dimension), "the actual kernel publishes " + dimension);
		}
		String export = System.getProperty("rdf4j.test.captureMemoizedPredictor");
		if (export != null) {
			Path destination = Path.of(export);
			Files.createDirectories(destination);
			Files.copy(directory.resolveSibling(directory.getFileName() + ".operators"),
					destination.resolve("old-memoized-resource.operators"));
			Files.writeString(destination.resolve("old-contract.txt"), descriptor.logicalKey().externalForm() + "\n"
					+ descriptor.physicalKey().externalForm() + "\n" + descriptor.applicability().externalForm()
					+ "\n" + contract.rawPrediction() + "\n");
		}
	}

	private static RuntimeFeedbackContract actualMemoizedPrediction(LmdbEstimatorRuntime runtime, double rhsPrice) {
		return actualMemoizedPrediction(runtime, rhsPrice, Double.NaN, Double.NaN);
	}

	private static RuntimeFeedbackContract actualMemoizedPrediction(LmdbEstimatorRuntime runtime, double rhsPrice,
			double startup, double fixed) {
		var factory = SimpleValueFactory.getInstance();
		var source = new LeftJoin(new StatementPattern(Var.of("subject"),
				Var.of("predicate", factory.createIRI("urn:memoized:left")), Var.of("left")),
				new StatementPattern(Var.of("subject"),
						Var.of("predicate", factory.createIRI("urn:memoized:right")), Var.of("right")));
		var model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relation) {
				return query.isStatementPattern(relation)
						? query.statementPatternValue(relation, 1).stringValue().equals("urn:memoized:left")
								? 1_000.0d
								: 1_000_000.0d
						: Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				var learning = new LmdbMappedFrontierLearningSession(runtime, query, true);
				int[] factors = new int[2];
				int factorCount = 0;
				for (int relation = 1; relation <= query.relationCount(); relation++) {
					if (query.isStatementPattern(relation)) {
						factors[factorCount++] = relation;
					}
				}
				assertEquals(2, factorCount);
				return new PackedCostSession() {
					@Override
					public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
						if (query.isStatementPattern(relation)) {
							double rows = estimateRows(query, relation);
							output.setRows(rows, rows);
						}
					}

					@Override
					public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
						if (query.isStatementPattern(relation)) {
							assertEquals(1_000.0d, context.prefixRows());
							output.setContextualRows(1_000.0d, rhsPrice);
							output.setInclusivePhysicalCost(100_000.0d, 2_000.0d, 3_000.0d, 4_000.0d, 5_000.0d,
									6_000.0d, 7_000.0d, 8_000.0d, 9_000.0d, 10_000.0d);
							output.setInvocations(context.prefixRows());
							if (Double.isFinite(startup)) {
								double perInvocation = (rhsPrice - startup - fixed) / context.prefixRows();
								output.setDependentCostComponents(startup, context.prefixRows(), 0.0d,
										perInvocation, perInvocation, 0.0d, 0.0d, fixed, 0.0d, 0.0d, 0.0d, 0.0d,
										0.0d, 0.0d, 0.0d);
							}
							output.setObjectiveInterval(rhsPrice, rhsPrice, rhsPrice);
						}
					}

					@Override
					public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
						if (query.childCount(relation) == 2 && !query.isInnerJoin(relation)) {
							output.setOutputRowsPreservingPhysicalCost(1_000.0d);
							output.putPlannedDoubleMetric("optimizer.memoizedCorrelationDistinctKeys", 1.0d);
						}
					}

					@Override
					public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
						learning.applyPhysicalIntermediateJoin(factors, context, output);
					}

					@Override
					public double objectiveScore(PackedCostEstimate output) {
						return Double.isFinite(output.objectivePoint()) ? output.objectivePoint() : output.workRows();
					}
				};
			}
		};
		var result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(source, PhysicalProperties.ANY),
				model);
		assertTrue(result.exactComplete());
		assertEquals("memoized-correlated",
				result.selectedPlan().getStringMetricPlanned("optimizer.physicalJoinImplementation"));
		assertEquals(1_000.0d, result.outputRows());
		RuntimeFeedbackContract contract = result.selectedPlan().getRuntimeFeedbackContract();
		assertNotNull(contract);
		return contract;
	}

	@ParameterizedTest
	@CsvSource({ "source,100", "seeks,2", "opens,4", "expressions,1004", "build,5", "probe,6", "paths,7",
			"results,1008", "remote,9", "peak,10000" })
	void actualMemoizedPredictionUsesDeclaredRightResourceAxes(String axis, double expected) {
		RuntimeFeedbackContract contract = actualMemoizedPrediction(mock(LmdbEstimatorRuntime.class), 110_000.0d);
		assertTrue(contract.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
		var raw = contract.rawPrediction();
		double actual = switch (axis) {
		case "source" -> raw.sourceRows();
		case "seeks" -> raw.randomSeeks();
		case "opens" -> raw.iteratorOpens();
		case "expressions" -> raw.expressionEvaluations();
		case "build" -> raw.hashBuildRows();
		case "probe" -> raw.hashProbeRows();
		case "paths" -> raw.pathExpansions();
		case "results" -> raw.resultRows();
		case "remote" -> raw.remoteCalls();
		case "peak" -> raw.peakMemoryRows();
		default -> throw new AssertionError(axis);
		};
		assertEquals(expected, actual, "the complete RHS weighted price is independent of " + axis);
	}

	@Test
	void actualMemoizedNumericPriceVariationKeepsOnePredictor() {
		var first = actualMemoizedPrediction(mock(LmdbEstimatorRuntime.class), 110_000.0d);
		var second = actualMemoizedPrediction(mock(LmdbEstimatorRuntime.class), 120_000.0d);
		var a = (LmdbRuntimeFeedbackDescriptor) first.descriptor();
		var b = (LmdbRuntimeFeedbackDescriptor) second.descriptor();
		assertEquals(a.logicalKey(), b.logicalKey());
		assertEquals(a.applicability(), b.applicability());
		assertEquals(a.physicalKey(), b.physicalKey(), "forecast variation is not a new predictor definition");
	}

